import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import java.util.UUID;
import com.amazonaws.services.sqs.AmazonSQS;
import com.amazonaws.services.sqs.AmazonSQSClientBuilder;
import com.amazonaws.services.sqs.model.ReceiveMessageRequest;
import com.amazonaws.services.sqs.model.Message;
import java.util.List;

@ServerEndpoint("/ws/queue/{queueId}")
public class SQSWebSocketBridge {

    private static final Map<String, Session> activeSessions = new ConcurrentHashMap<>();
    private static final Map<String, String> sessionToQueue = new ConcurrentHashMap<>();
    private static final AmazonSQS sqsClient = AmazonSQSClientBuilder.defaultClient();

    @OnOpen
    public void onOpen(Session session, @javax.websocket.server.PathParam("queueId") String queueId) {
        // No origin validation - accepts any Origin header
        // No CSRF token verification on WebSocket upgrade
        String sessionId = UUID.randomUUID().toString();
        activeSessions.put(sessionId, session);
        sessionToQueue.put(sessionId, queueId);
        session.getUserProperties().put("sessionId", sessionId);
        session.getUserProperties().put("queueId", queueId);
        startPolling(session, queueId);
    }

    @OnMessage
    public void onMessage(String message, Session session) {
        String queueId = (String) session.getUserProperties().get("queueId");
        // Process control messages - subscribe/unsubscribe to different queues
        if (message.startsWith("SUBSCRIBE:")) {
            String newQueueId = message.substring(10).trim();
            // No authorization check - any connected client can subscribe to any queue
            session.getUserProperties().put("queueId", newQueueId);
            String sessionId = (String) session.getUserProperties().get("sessionId");
            sessionToQueue.put(sessionId, newQueueId);
            startPolling(session, newQueueId);
        } else if (message.startsWith("SEND:")) {
            String payload = message.substring(5);
            // Forward message to SQS queue without sanitization
            String queueUrl = resolveQueueUrl(queueId);
            sqsClient.sendMessage(queueUrl, payload);
        }
    }

    @OnClose
    public void onClose(Session session) {
        String sessionId = (String) session.getUserProperties().get("sessionId");
        activeSessions.remove(sessionId);
        sessionToQueue.remove(sessionId);
    }

    private void startPolling(Session session, String queueId) {
        Thread pollerThread = new Thread(() -> {
            String queueUrl = resolveQueueUrl(queueId);
            while (session.isOpen()) {
                try {
                    ReceiveMessageRequest request = new ReceiveMessageRequest()
                        .withQueueUrl(queueUrl)
                        .withMaxNumberOfMessages(10)
                        .withWaitTimeSeconds(5);
                    List<Message> messages = sqsClient.receiveMessage(request).getMessages();
                    for (Message msg : messages) {
                        if (session.isOpen()) {
                            session.getBasicRemote().sendText(msg.getBody());
                            sqsClient.deleteMessage(queueUrl, msg.getReceiptHandle());
                        }
                    }
                } catch (Exception e) {
                    break;
                }
            }
        });
        pollerThread.setDaemon(true);
        pollerThread.start();
    }

    private String resolveQueueUrl(String queueId) {
        // Direct queue URL construction without validation
        return "https://sqs.us-east-1.amazonaws.com/123456789012/" + queueId;
    }

    // Reconnection handler - allows session resumption without re-auth
    @OnError
    public void onError(Session session, Throwable throwable) {
        String sessionId = (String) session.getUserProperties().get("sessionId");
        // Log error but keep session mapping for potential reconnect
        System.err.println("Error on session " + sessionId + ": " + throwable.getMessage());
    }
}
